#!/usr/bin/env python
"""Churn pipeline flow.

Crew 1 (Data Analyst) -> handoff gates -> Crew 2 (Data Scientist) -> quality gate.

The gates are plain Python (churn_pipeline.gates). When a handoff gate fails,
the flow writes validation_report.md and stops before Crew 2; when the model
misses the quality thresholds, it writes the report and does not approve the
model. Either way the command exits with 1.

`uv run kickoff --from-gate` skips Crew 1 and starts at the handoff gates with
the files already in artifacts/latest/crew1, to show a broken handoff fast.
"""
import json
import logging
import sys
from datetime import datetime, timezone
from pathlib import Path

from crewai.flow import Flow, listen, router, start
from pydantic import BaseModel

from churn_pipeline.crews.analyst_crew.analyst_crew import AnalystCrew
from churn_pipeline.crews.scientist_crew.scientist_crew import ScientistCrew
from churn_pipeline.gates import (
    GateResult,
    gate_model_quality,
    run_handoff_gates,
    write_validation_report,
)
from churn_pipeline.run_history import record_run, run_row

ROOT = Path(__file__).resolve().parents[2]
log = logging.getLogger("churn_pipeline")


class PipelineState(BaseModel):
    raw_data_path: str = str(ROOT / "data" / "raw" / "E Commerce Dataset.xlsx")
    output_dir: str = str(ROOT / "artifacts" / "latest" / "crew1")
    crew2_output_dir: str = str(ROOT / "artifacts" / "latest" / "crew2")
    lock_path: str = str(ROOT / "contracts" / "dataset_contract.lock.json")
    report_path: str = str(ROOT / "artifacts" / "latest" / "validation_report.md")
    from_gate: bool = False
    # "pipeline" for a normal run, "scenario" when break_it.py runs it on broken data.
    run_kind: str = "pipeline"
    scenario: str | None = None
    gates: list[dict] = []
    status: str = "running"


class ChurnPipelineFlow(Flow[PipelineState]):

    def _record(self, results: list[GateResult]) -> None:
        for g in results:
            self.state.gates.append(g.to_dict())
            log.info("gate %-18s %s  %s", g.name, "PASS" if g.passed else "FAIL", g.summary)
            for p in g.problems:
                log.info("    - %s", p)

    def _finish(self, status: str, verdict: str, next_step: str) -> dict:
        self.state.status = status
        when = datetime.now(timezone.utc)
        write_validation_report(self.state.report_path,
                                [GateResult(**g) for g in self.state.gates], verdict, next_step, when)
        log.info("%s: %s (report: %s)", verdict, next_step, self.state.report_path)
        metrics_path = Path(self.state.crew2_output_dir) / "evaluation_metrics.json"
        metrics = json.loads(metrics_path.read_text(encoding="utf-8")) if metrics_path.is_file() else None
        log.info(record_run(run_row(when.isoformat(timespec="seconds"), self.state.run_kind,
                                    self.state.scenario, status, verdict, self.state.gates,
                                    next_step, metrics)))
        return {"status": status, "report": self.state.report_path, "gates": self.state.gates}

    @start()
    def run_analyst_crew(self):
        if self.state.from_gate:
            log.info("--from-gate: skipping Crew 1, using %s", self.state.output_dir)
            return
        log.info("Crew 1 (Data Analyst) starting on %s", self.state.raw_data_path)
        Path(self.state.output_dir).mkdir(parents=True, exist_ok=True)
        AnalystCrew().crew().kickoff(inputs={
            "raw_data_path": self.state.raw_data_path,
            "output_dir": self.state.output_dir,
        })
        log.info("Crew 1 finished")

    @router(run_analyst_crew)
    def handoff_gates(self):
        results = run_handoff_gates(self.state.output_dir, self.state.lock_path)
        self._record(results)
        return "handoff_passed" if all(g.passed for g in results) else "handoff_failed"

    @listen("handoff_failed")
    def stop_before_crew2(self):
        return self._finish("handoff_failed", "FAILED",
                            "Crew 2 did not run: fix the data or Crew 1, or update the locked "
                            "contract on purpose, then run again")

    @listen("handoff_passed")
    def run_scientist_crew(self):
        # Crew 2 reads only Crew 1's clean_data.csv and dataset_contract.json.
        log.info("Crew 2 (Data Scientist) starting on %s", self.state.output_dir)
        ScientistCrew().crew().kickoff(inputs={
            "input_dir": self.state.output_dir,
            "output_dir": self.state.crew2_output_dir,
        })
        log.info("Crew 2 finished")

    @router(run_scientist_crew)
    def quality_gate(self):
        result = gate_model_quality(self.state.crew2_output_dir)
        self._record([result])
        approval = Path(self.state.crew2_output_dir) / "model_approved.json"
        approval.unlink(missing_ok=True)
        if not result.passed:
            return "model_rejected"
        approval.write_text(json.dumps({"model": "model.joblib", "gate": result.to_dict()}, indent=2) + "\n",
                            encoding="utf-8")
        return "model_accepted"

    @listen("model_rejected")
    def reject_model(self):
        return self._finish("model_rejected", "FAILED",
                            "the model misses the quality thresholds and is not approved")

    @listen("model_accepted")
    def approve_model(self):
        return self._finish("passed", "PASSED", "model approved (model_approved.json written)")


def _setup_logging(log_path: Path) -> None:
    # Replace earlier handlers, so several runs in one process (break_it.py)
    # each get their own log file.
    for h in list(log.handlers):
        log.removeHandler(h)
        h.close()
    log_path.parent.mkdir(parents=True, exist_ok=True)
    handlers = [logging.FileHandler(log_path, mode="w", encoding="utf-8"), logging.StreamHandler()]
    fmt = logging.Formatter("%(asctime)s %(levelname)s %(message)s", "%Y-%m-%d %H:%M:%S")
    for h in handlers:
        h.setFormatter(fmt)
        log.addHandler(h)
    log.setLevel(logging.INFO)


def kickoff():
    # No return value: the console script passes it to sys.exit. Exit code 1
    # means a gate failed.
    from_gate = "--from-gate" in sys.argv[1:]
    _setup_logging(ROOT / "artifacts" / "latest" / "pipeline.log")
    result = ChurnPipelineFlow().kickoff(inputs={"from_gate": from_gate})
    print(json.dumps(result, indent=2))
    if result["status"] != "passed":
        sys.exit(1)


def plot():
    ChurnPipelineFlow().plot()


def run_with_trigger():
    """Run the flow with a JSON trigger payload of state overrides."""
    if len(sys.argv) < 2:
        raise Exception("No trigger payload provided. Please provide JSON payload as argument.")
    try:
        payload = json.loads(sys.argv[1])
    except json.JSONDecodeError:
        raise Exception("Invalid JSON payload provided as argument")
    return ChurnPipelineFlow().kickoff(inputs=payload)


if __name__ == "__main__":
    kickoff()

"""Validation gates of the churn pipeline flow.

Plain Python, no LLM: each gate returns a GateResult, and the flow routes on
them. The handoff gates run between Crew 1 and Crew 2; the quality gate runs
after Crew 2.
"""
from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import pandas as pd

from churn_pipeline.contract.models import DatasetContract, load_contract
from churn_pipeline.contract.validator import validate_against_contract

CREW1_ARTIFACTS = [
    "quality_report.json",
    "quality_summary.md",
    "clean_data.csv",
    "preparation_log.md",
    "eda_report.html",
    "insights.md",
    "contract_numbers.json",
    "dataset_contract.json",
]

CREW2_ARTIFACTS = [
    "contract_review.md",
    "features.csv",
    "feature_spec.json",
    "feature_log.md",
    "model.joblib",
    "evaluation_metrics.json",
    "evaluation_report.md",
    "model_card.md",
]

# Written by the agents, so they change wording from run to run; the lock
# compares every number and rule, not this text.
TEXT_FIELDS = {"description", "assumptions", "leakage_notes"}


@dataclass
class GateResult:
    name: str
    passed: bool
    summary: str
    problems: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


def _missing_files(directory: str | Path, names: list[str]) -> list[str]:
    d = Path(directory)
    return [f for f in names if not (d / f).is_file() or (d / f).stat().st_size == 0]


# ------------------------------------------------------------ handoff gates

def gate_crew1_artifacts(crew1_dir: str | Path) -> GateResult:
    missing = _missing_files(crew1_dir, CREW1_ARTIFACTS)
    if missing:
        return GateResult("crew1_artifacts", False, f"{len(missing)} Crew 1 artifacts missing or empty",
                          [f"{f} is missing or empty" for f in missing])
    return GateResult("crew1_artifacts", True, f"all {len(CREW1_ARTIFACTS)} Crew 1 artifacts present")


def gate_contract_vs_data(crew1_dir: str | Path) -> GateResult:
    d = Path(crew1_dir)
    data = d / "clean_data.csv"
    violations = validate_against_contract(
        pd.read_csv(data), load_contract(d / "dataset_contract.json"), file_path=data)
    if violations:
        return GateResult("contract_vs_data", False,
                          f"clean_data.csv breaks dataset_contract.json ({len(violations)} violations)",
                          [v.message for v in violations])
    return GateResult("contract_vs_data", True, "clean_data.csv matches dataset_contract.json")


def _without_text(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: _without_text(v) for k, v in value.items() if k not in TEXT_FIELDS}
    if isinstance(value, list):
        return [_without_text(v) for v in value]
    return value


def _diff(locked: Any, current: Any, path: str) -> list[str]:
    if isinstance(locked, dict) and isinstance(current, dict):
        out = []
        for key in sorted(set(locked) | set(current)):
            sub = f"{path}.{key}" if path else key
            if key not in current:
                out.append(f"{sub} is in the locked contract but missing from the new one")
            elif key not in locked:
                out.append(f"{sub} is new: {current[key]!r} (not in the locked contract)")
            else:
                out += _diff(locked[key], current[key], sub)
        return out
    if locked != current:
        return [f"{path}: locked {locked!r}, new {current!r}"]
    return []


def gate_locked_contract(crew1_dir: str | Path, lock_path: str | Path) -> GateResult:
    """Compare the contract Crew 1 just wrote with the approved, locked one.

    Columns are matched by name, so a renamed or dropped column is reported
    by name rather than as a shifted list.
    """
    locked = _without_text(json.loads(Path(lock_path).read_text(encoding="utf-8")))
    current = _without_text(json.loads((Path(crew1_dir) / "dataset_contract.json").read_text(encoding="utf-8")))
    for c in (locked, current):
        c["columns"] = {col["name"]: col for col in c.get("columns", [])}
    problems = _diff(locked, current, "")
    if problems:
        return GateResult("locked_contract", False,
                          f"dataset_contract.json differs from the locked contract ({len(problems)} differences)",
                          problems)
    return GateResult("locked_contract", True, "dataset_contract.json matches the locked contract")


def gate_required_features(crew1_dir: str | Path, lock_path: str | Path) -> GateResult:
    """Every feature the locked contract promises must be in clean_data.csv and usable."""
    locked = load_contract(lock_path)
    required = [c.name for c in locked.columns
                if c.role == "feature" and c.name not in locked.forbidden_features]
    columns = set(pd.read_csv(Path(crew1_dir) / "clean_data.csv", nrows=0).columns)
    contract: DatasetContract = load_contract(Path(crew1_dir) / "dataset_contract.json")
    usable = {c.name for c in contract.columns
              if c.role == "feature" and c.name not in contract.forbidden_features}
    problems = [f"required feature {n!r} is not in clean_data.csv" for n in required if n not in columns]
    problems += [f"required feature {n!r} is not a usable feature in dataset_contract.json"
                 for n in required if n in columns and n not in usable]
    if problems:
        return GateResult("required_features", False,
                          f"{len(problems)} of {len(required)} required features unavailable", problems)
    return GateResult("required_features", True, f"all {len(required)} required features available")


def run_handoff_gates(crew1_dir: str | Path, lock_path: str | Path) -> list[GateResult]:
    """Gates between Crew 1 and Crew 2. Stops after the first gate whose
    failure makes the later ones meaningless (missing files)."""
    first = gate_crew1_artifacts(crew1_dir)
    if not first.passed:
        return [first]
    return [
        first,
        gate_contract_vs_data(crew1_dir),
        gate_locked_contract(crew1_dir, lock_path),
        gate_required_features(crew1_dir, lock_path),
    ]


# -------------------------------------------------------------- quality gate

def gate_model_quality(crew2_dir: str | Path) -> GateResult:
    d = Path(crew2_dir)
    missing = _missing_files(d, CREW2_ARTIFACTS)
    if missing:
        return GateResult("model_quality", False, f"{len(missing)} Crew 2 artifacts missing or empty",
                          [f"{f} is missing or empty" for f in missing])
    metrics = json.loads((d / "evaluation_metrics.json").read_text(encoding="utf-8"))
    test = metrics["selected_test_metrics"]
    problems = [f"test {k} is {test[k]:.4f}, below the threshold {v:.2f}"
                for k, v in metrics["quality_thresholds"].items() if test[k] < v]
    if metrics["split"]["duplicate_groups_on_both_sides"]:
        problems.append(f"{metrics['split']['duplicate_groups_on_both_sides']} duplicate groups "
                        "are in both train and test, so the test scores are inflated")
    scores = ", ".join(f"{k} {test[k]:.4f} (min {v:.2f})" for k, v in metrics["quality_thresholds"].items())
    if problems:
        return GateResult("model_quality", False, f"{metrics['selected_model']} fails: {scores}", problems)
    return GateResult("model_quality", True, f"{metrics['selected_model']} passes: {scores}")


# ---------------------------------------------------------------- reporting

def write_validation_report(path: str | Path, gates: list[GateResult], verdict: str,
                            next_step: str, when: datetime | None = None) -> None:
    when = when or datetime.now(timezone.utc)
    lines = [
        "# Validation report",
        "",
        f"- Verdict: **{verdict}**",
        f"- Time (UTC): {when.strftime('%Y-%m-%d %H:%M:%S')}",
        f"- Next step: {next_step}",
        "",
        "| Gate | Result | Summary |",
        "|---|---|---|",
    ]
    lines += [f"| {g.name} | {'PASS' if g.passed else 'FAIL'} | {g.summary} |" for g in gates]
    for g in gates:
        if g.problems:
            lines += ["", f"## {g.name}", ""] + [f"- {p}" for p in g.problems]
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text("\n".join(lines) + "\n", encoding="utf-8")

"""Retrieval over Harbor & Vale's internal documents (the RAG part of the project).

The corpus is the synthetic internal documents in knowledge/harbor_vale/ plus
the latest insights and model card the crews wrote. Markdown files are split
into one chunk per "## " section, embedded with OpenAI, and searched by cosine
similarity. Embeddings are cached in artifacts/rag/index.json by the text's
sha256, so only new or changed sections are embedded again.

Plain Python like the other tools: the agent decides what to ask and how to
use the answer; this module returns the sections with their source.
"""
from __future__ import annotations

import hashlib
import json
import os
import threading
from dataclasses import dataclass
from pathlib import Path
from typing import Callable, Sequence

import numpy as np
from crewai.tools import tool

ROOT = Path(__file__).resolve().parents[2]
EMBEDDING_MODEL = "text-embedding-3-small"
DEFAULT_SOURCES = [
    *sorted((ROOT / "knowledge" / "harbor_vale").glob("*.md")),
    ROOT / "artifacts" / "latest" / "crew1" / "insights.md",
    ROOT / "artifacts" / "latest" / "crew2" / "model_card.md",
]
CACHE_PATH = ROOT / "artifacts" / "rag" / "index.json"
TOP_K = 4

Embedder = Callable[[Sequence[str]], np.ndarray]


@dataclass(frozen=True)
class Chunk:
    source: str
    title: str
    section: str
    text: str

    @property
    def sha256(self) -> str:
        return hashlib.sha256(self.text.encode("utf-8")).hexdigest()


def split_markdown(path: str | Path, root: Path = ROOT) -> list[Chunk]:
    """One chunk per "## " section; text before the first one is the "Overview" chunk.

    Each chunk starts with "<title> > <section>" so a section keeps its context
    when it is retrieved on its own.
    """
    path = Path(path)
    try:
        source = str(path.resolve().relative_to(root))
    except ValueError:
        source = path.name
    title, section, body, chunks = path.stem, "Overview", [], []

    def flush() -> None:
        text = "\n".join(body).strip()
        if text:
            chunks.append(Chunk(source, title, section, f"{title} > {section}\n{text}"))

    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("# ") and not chunks and not body:
            title = line[2:].strip()
        elif line.startswith("## "):
            flush()
            section, body = line[3:].strip(), []
        else:
            body.append(line)
    flush()
    return chunks


def openai_embedder(model: str = EMBEDDING_MODEL) -> Embedder:
    from openai import OpenAI

    client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

    def embed(texts: Sequence[str]) -> np.ndarray:
        response = client.embeddings.create(model=model, input=list(texts))
        return np.array([d.embedding for d in response.data], dtype=float)

    return embed


def _unit(vectors: np.ndarray) -> np.ndarray:
    norms = np.linalg.norm(vectors, axis=1, keepdims=True)
    return vectors / np.where(norms == 0, 1, norms)


class DocIndex:
    def __init__(self, chunks: list[Chunk], vectors: np.ndarray, embedder: Embedder):
        self.chunks = chunks
        self.vectors = _unit(vectors)
        self.embedder = embedder

    @classmethod
    def build(cls, sources: Sequence[str | Path], embedder: Embedder,
              cache_path: str | Path | None = None, model: str = EMBEDDING_MODEL) -> DocIndex:
        """Chunk every existing source and embed only the chunks the cache lacks."""
        chunks = [c for s in sources if Path(s).is_file() for c in split_markdown(s)]
        cached: dict[str, list[float]] = {}
        cache = Path(cache_path) if cache_path else None
        if cache and cache.is_file():
            stored = json.loads(cache.read_text(encoding="utf-8"))
            if stored.get("model") == model:
                cached = stored["vectors"]
        missing = [c for c in chunks if c.sha256 not in cached]
        if missing:
            for c, v in zip(missing, embedder([c.text for c in missing])):
                cached[c.sha256] = [float(x) for x in v]
        if cache:
            cache.parent.mkdir(parents=True, exist_ok=True)
            keep = {c.sha256: cached[c.sha256] for c in chunks}
            # Write then rename, so a reader never sees a half-written file.
            tmp = cache.with_suffix(f".{os.getpid()}.tmp")
            tmp.write_text(json.dumps({"model": model, "vectors": keep}), encoding="utf-8")
            tmp.replace(cache)
        vectors = np.array([cached[c.sha256] for c in chunks], dtype=float)
        return cls(chunks, vectors, embedder)

    def citations(self) -> set[str]:
        """Every "file name > section" an agent may cite."""
        return {f"{Path(c.source).name} > {c.section}" for c in self.chunks}

    def search(self, query: str, k: int = TOP_K) -> list[dict]:
        q = _unit(np.asarray(self.embedder([query]), dtype=float))[0]
        scores = self.vectors @ q
        best = np.argsort(scores)[::-1][:k]
        return [{"source": self.chunks[i].source, "section": self.chunks[i].section,
                 "cite_as": f"[{Path(self.chunks[i].source).name} > {self.chunks[i].section}]",
                 "score": round(float(scores[i]), 4), "text": self.chunks[i].text}
                for i in best]


_index: DocIndex | None = None
_index_lock = threading.Lock()


def default_index() -> DocIndex:
    """The project corpus, built once per process. Agents may call the search
    tool in parallel, so the first build is guarded by a lock."""
    global _index
    with _index_lock:
        if _index is None:
            _index = DocIndex.build(DEFAULT_SOURCES, openai_embedder(), CACHE_PATH)
    return _index


@tool("search_internal_docs")
def search_internal_docs_tool(query: str) -> str:
    """Search Harbor & Vale's internal documents (retention playbook, discount policy, past
    campaign results, competitor offers, the unit-change postmortem, the latest churn insights
    and model card). Returns the most relevant sections as JSON, each with its source file and
    section name to cite."""
    return json.dumps(default_index().search(query), ensure_ascii=False)

import os
import re
from pathlib import Path

from crewai import LLM, Agent, Crew, Process, Task
from crewai.agents.agent_builder.base_agent import BaseAgent
from crewai.project import CrewBase, after_kickoff, agent, before_kickoff, crew, task

from churn_pipeline.crews.briefing_crew.outputs import BriefingNotes
from churn_pipeline.news import SEEN_ARTICLES, search_recent_news
from churn_pipeline.rag import search_internal_docs_tool
from churn_pipeline.retention_plan import all_citations
from churn_pipeline.tools.briefing_tools import (
    customer_risk_profile,
    customer_risk_profile_tool,
    search_recent_news_tool,
)

MAX_WORDS = 650  # about one printed page
MAX_WHY_WORDS = 25
MAX_SUMMARY_WORDS = 50
MAX_RELEVANCE_WORDS = 30
BAND_RULE = {"high": "0.70 or higher", "medium": "0.40 to 0.70", "low": "below 0.40"}
# An explanation must not walk back a decision; these phrases did in earlier,
# free-form briefings (scripts/audit_briefings.py).
CONTRADICTIONS = re.compile(r"no individual outreach|regular newsletter|"
                            r"(not be contacted|do not contact (this|the) customer)(?! more than)", re.I)
# Only these say whether to contact; the frequency note rightly says "not more than twice".
CONTACT_IDS = {"contact", "channel"}


def _llm() -> LLM:
    # temperature=0 keeps agent wording as repeatable as the model allows;
    # the numbers and the decisions always come from code.
    return LLM(model=os.getenv("MODEL", "gpt-4.1-mini"), temperature=0)


def _words(text: str) -> int:
    """Words a reader reads: a markdown link's target URL does not count."""
    return len(re.findall(r"\S+", re.sub(r"\]\([^)]*\)", "]", text)))


def check_notes(notes: BriefingNotes, profile: dict, articles: dict[str, dict]) -> list[str]:
    """Problems that make the agent's notes unusable; empty means the briefing may be rendered.

    The decisions themselves come from the plan, so this checks that the agent
    explained every one of them, explained nothing else, did not walk any back,
    and linked only articles the news search returned.
    """
    plan = profile["plan"]
    problems = []
    expected = [d["id"] for d in plan["decisions"]]
    given = [n.id for n in notes.decisions]
    missing, extra = [i for i in expected if i not in given], [i for i in given if i not in expected]
    if missing:
        problems.append(f"explain every decision in the plan; missing ids: {missing}")
    if extra:
        problems.append(f"these ids are not decisions in the plan: {extra}")
    for n in notes.decisions:
        if not n.why.strip():
            problems.append(f"the explanation for {n.id} is empty")
        elif _words(n.why) > MAX_WHY_WORDS:
            problems.append(f"the explanation for {n.id} is longer than {MAX_WHY_WORDS} words")
        if plan["contact"] and n.id in CONTACT_IDS and CONTRADICTIONS.search(n.why):
            problems.append(f"the explanation for {n.id} contradicts the plan: this customer must be contacted")
    if plan["contact"] and CONTRADICTIONS.search(notes.summary):
        problems.append("the summary contradicts the plan: this customer must be contacted")
    if _words(notes.summary) > MAX_SUMMARY_WORDS:
        problems.append(f"the summary is longer than {MAX_SUMMARY_WORDS} words")
    for m in notes.market:
        if _words(m.relevance) > MAX_RELEVANCE_WORDS:
            problems.append(f"a market relevance note is longer than {MAX_RELEVANCE_WORDS} words")
    invented = [m.url for m in notes.market if m.url not in articles]
    if invented:
        problems.append(f"these links did not come from search_recent_news: {invented[:3]}; "
                        "copy url exactly from the search result")
    if _words(render_briefing(profile, notes, articles)) > MAX_WORDS:
        problems.append(f"the briefing is longer than {MAX_WORDS} words; shorten the explanations")
    return problems


def render_briefing(profile: dict, notes: BriefingNotes, articles: dict[str, dict]) -> str:
    """The briefing in markdown. Facts, score and decisions come from code; the agent's
    text fills only the summary, the "why" of each decision and the news relevance."""
    plan = profile["plan"]
    why = {n.id: n.why.strip() for n in notes.decisions}
    band = profile["risk_band"]
    facts = " · ".join(f"{k} {'missing' if v is None else v}" for k, v in profile["key_facts"].items())
    lines = [f"# Retention briefing: customer {profile['customer_id']}", "", notes.summary.strip(), "",
             "## Customer snapshot", f"- {facts}",
             "", "## Churn risk",
             f"- Risk score: {profile['risk_score']:.2f} ({band} risk band: {BAND_RULE[band]}). "
             f"{profile['score_note'][0].upper()}{profile['score_note'][1:]}.",
             "", "## Plan (decided in code from the playbook and the discount policy)"]
    for d in plan["decisions"]:
        lines.append(f"- **{d['label']}:** {d['value']}. {why.get(d['id'], '')} {' '.join(d['cites'])}".rstrip())
    lines += ["", "## Do not"] + [f"- {n['value']} {' '.join(n['cites'])}" for n in plan["never"]]
    lines += ["", "## Market now (last 48 hours)"]
    items = [(articles[m.url], m.relevance.strip()) for m in notes.market if m.url in articles]
    if items:
        lines += [f"- [{a['title']}]({a['url']}), {a['source']}, {a['published']}. {rel}" for a, rel in items]
    else:
        lines.append("- No market news from the last 48 hours was available.")
    lines += ["", "## Sources", " · ".join(sorted(all_citations(plan)))]
    return "\n".join(lines) + "\n"


@CrewBase
class BriefingCrew:
    """Retention briefing: approved churn model + retention plan + internal documents (RAG) + news."""

    agents: list[BaseAgent]
    tasks: list[Task]

    agents_config = "config/agents.yaml"
    tasks_config = "config/tasks.yaml"

    @agent
    def retention_briefing_writer(self) -> Agent:
        return Agent(
            config=self.agents_config["retention_briefing_writer"],  # type: ignore[index]
            llm=_llm(),
            tools=[customer_risk_profile_tool, search_internal_docs_tool, search_recent_news_tool],
            max_iter=10,
            verbose=True,
        )

    @before_kickoff
    def require_customer(self, inputs: dict) -> dict:
        """Score the customer and decide the plan in code first: no approved model or
        unknown customer, no briefing."""
        self._profile = customer_risk_profile(int(inputs["customer_id"]))
        # Searched here first so the news is known before the agent writes.
        search_recent_news(self._profile["news_query"])
        self._out = Path(inputs["output_dir"]) / f"customer_{inputs['customer_id']}.md"
        self._out.parent.mkdir(parents=True, exist_ok=True)
        return inputs

    def _guardrail(self, output):
        notes = output.pydantic
        if not isinstance(notes, BriefingNotes):
            return False, "return the structured BriefingNotes"
        problems = check_notes(notes, self._profile, SEEN_ARTICLES)
        return (False, "; ".join(problems)) if problems else (True, output)

    @after_kickoff
    def write_briefing(self, result):
        self._out.write_text(render_briefing(self._profile, result.pydantic, SEEN_ARTICLES), encoding="utf-8")
        return result

    @task
    def write_briefing_task(self) -> Task:
        return Task(
            config=self.tasks_config["write_briefing_task"],  # type: ignore[index]
            output_pydantic=BriefingNotes,
            guardrail=self._guardrail,
            guardrail_max_retries=2,
        )

    @crew
    def crew(self) -> Crew:
        """Creates the Retention Briefing Crew."""
        return Crew(
            agents=self.agents,
            tasks=self.tasks,
            process=Process.sequential,
            verbose=True,
        )
